// Geometry facts about each plane's 3D model, generated by `npm run models` into src/data/planeModels.json.
// The simulation uses them for muzzle positions and hit-sphere sizes; planes without a model yet get
// era-typical defaults, so everything still works while models are added over Days 4, 7 and 9.
import type { EraId, MissileClassId, MissileMount, Plane } from '../data/types';
import raw from '../data/planeModels.json';
import type { Vec3 } from './math';

export interface PlaneModelInfo {
  file: string;
  lengthM: number;
  wingspanM: number;
  heightM: number;
  tris: number;
  muzzles: { pos: Vec3; mount: number }[];
  pylons: Vec3[];
  exhausts: Vec3[];
  prop: Vec3 | null;
}

export const PLANE_MODELS = raw as unknown as Record<string, PlaneModelInfo>;

const PROP_ERAS: readonly EraId[] = ['ww1', 'early_ww2', 'late_ww2'];
export const isProp = (era: EraId): boolean => PROP_ERAS.includes(era);

/** Length and span in metres: from the model, or a typical size for the era. */
export function planeSize(plane: Plane): { lengthM: number; wingspanM: number } {
  const m = PLANE_MODELS[plane.id];
  if (m) return { lengthM: m.lengthM, wingspanM: m.wingspanM };
  if (plane.era === 'ww1') return { lengthM: 6.5, wingspanM: 9 };
  if (isProp(plane.era)) return { lengthM: 9.5, wingspanM: 11.5 };
  return { lengthM: 15, wingspanM: 10.5 };
}

/** Muzzle positions (plane-local metres) for one gun mount, or null to use the generic layout. */
export function muzzlesFor(planeId: string, mount: number): Vec3[] | null {
  const m = PLANE_MODELS[planeId];
  if (!m || m.muzzles.length === 0) return null;
  const own = m.muzzles.filter((x) => x.mount === mount).map((x) => x.pos);
  return own.length > 0 ? own : m.muzzles.map((x) => x.pos);
}

/** The weapon model drawn for each missile class (public/models/weapons). */
export const MISSILE_MODEL: Record<MissileClassId, string> = {
  ir_rear: 'missile_ir_small',
  ir_all_aspect: 'missile_ir_small',
  ir_hobs: 'missile_ir_large',
  radar_semi_active: 'missile_radar_medium',
  radar_active: 'missile_radar_long',
};

export interface PylonSlot {
  /** Index into the plane's missile mounts (planes.json `missiles`). */
  mount: number;
  /** Plane-local position of the missile's centre, just under the pylon. */
  pos: Vec3;
  model: string;
}

/**
 * Which missile hangs on which pylon. Radar missiles take the innermost pylons (fuselage and inner wing),
 * IR missiles the outermost (outer wing, wingtips), the way real loadouts usually go. Pylons come in
 * left/right pairs, so as a mount's count drops its last slot empties first and launches alternate sides.
 * A mount with more missiles than free pylons shows only what fits.
 */
export function pylonSlots(
  planeId: string,
  mounts: readonly MissileMount[],
  classOf: (missileType: string) => MissileClassId | undefined,
): PylonSlot[] {
  const pylons = PLANE_MODELS[planeId]?.pylons ?? [];
  if (pylons.length === 0 || mounts.length === 0) return [];
  // Pair each pylon with its mirror (same |x|, y, z); sort pairs inner → outer.
  const order = pylons.map((p, i) => ({ p, i })).sort((a, b) => Math.abs(a.p[0]) - Math.abs(b.p[0]) || b.p[2] - a.p[2] || b.p[0] - a.p[0]);
  const free = order.map((o) => o.p);
  const radar = (m: MissileMount): boolean => (classOf(m.type) ?? '').startsWith('radar');
  const out: PylonSlot[] = [];
  const take = (mount: number, n: number, fromOuter: boolean): void => {
    const cls = classOf(mounts[mount]!.type);
    if (!cls) return;
    for (let k = 0; k < n && free.length > 0; k++) {
      // Take whole pairs from the chosen end so both sides fill together.
      const p = fromOuter ? (k % 2 === 0 ? free.splice(Math.max(0, free.length - 2), 1)[0]! : free.pop()!) : free.shift()!;
      out.push({ mount, pos: [p[0], p[1] - HANG_M, p[2]], model: MISSILE_MODEL[cls] });
    }
  };
  mounts.forEach((m, i) => radar(m) && take(i, m.count, false));
  mounts.forEach((m, i) => !radar(m) && take(i, m.count, true));
  return out;
}

/** Missile centre below the pylon point. */
const HANG_M = 0.22;

/**
 * Rockets and bombs on an attacker's pylons: bombs on the innermost (the centreline or inner wing), rockets
 * outboard of them, in left/right pairs. Each slot says which it carries and its index, so a plane with
 * `rockets` and `bombs` left shows exactly that many.
 */
export function ordnanceSlots(planeId: string, ordnance: { rockets: number; bombs: number }): { kind: 'rocket' | 'bomb'; index: number; pos: Vec3 }[] {
  const pylons = [...(PLANE_MODELS[planeId]?.pylons ?? [])].sort((a, b) => Math.abs(a[0]) - Math.abs(b[0]) || b[0] - a[0]);
  const out: { kind: 'rocket' | 'bomb'; index: number; pos: Vec3 }[] = [];
  let i = 0;
  for (let k = 0; k < ordnance.bombs && i < pylons.length; k++, i++) {
    const p = pylons[i]!;
    out.push({ kind: 'bomb', index: k, pos: [p[0], p[1] - 0.3, p[2]] });
  }
  for (let k = 0; k < ordnance.rockets && i < pylons.length; k++, i++) {
    const p = pylons[i]!;
    out.push({ kind: 'rocket', index: k, pos: [p[0], p[1] - 0.15, p[2]] });
  }
  return out;
}

export const ORDNANCE_MODEL = { rocket: 'rocket', bomb: 'bomb_250' } as const;
